package ais.database.model.bsi;

import static javax.persistence.GenerationType.IDENTITY;

import java.util.Date;

import javax.persistence.Column;
import javax.persistence.Entity;
import javax.persistence.GeneratedValue;
import javax.persistence.Id;
import javax.persistence.Table;
import javax.persistence.Temporal;
import javax.persistence.TemporalType;




import org.hibernate.envers.Audited;



import ais.database.model.GeneralValueObject;

/**
 * Bank generated by hbm2java
 * <p>
 * Entitas <b>balasan bank</b> integrasi <i>host-to-host</i> BSI e-Collection:
 * satu baris tabel {@code public.bsi_response} merekam notifikasi status
 * pembayaran yang dikirim BSI ke AIS untuk sebuah {@link BsiRequest}.
 *
 * <h3>Pola umum</h3>
 *
 * Kelas ini adalah kaki keempat dari pola empat kelas yang dipakai seluruh
 * paket integrasi bank AIS. <b>Penjelasan lengkap pola tersebut ada pada
 * {@link ais.database.model.bni.BniRequest}</b> dan tidak diulang di sini.
 * Seperti pada paket lain, perlu dibedakan dua "respons":
 * {@link BsiRequest#getResponse_code()} merekam hasil <b>penerbitan</b>
 * tagihan/Virtual Account, sedangkan kelas ini merekam hasil
 * <b>pembayaran</b>. Tautannya searah dari header ke balasan lewat
 * {@link BsiRequest#getBsiResponse()} (kolom {@code bsi_response} pada tabel
 * {@code bsi_request}); kelas ini tidak menyimpan referensi balik, dan
 * pencocokan dilakukan {@code ais.action.servlet.Bsiresponse} berdasarkan
 * {@link #getTrxId() trxId}.
 *
 * <h3>Jalur masuknya data</h3>
 *
 * Berbeda dari paket BRI yang servlet balasannya tidak terpasang, BSI MEMILIKI
 * endpoint callback nyata: servlet {@code ais.action.servlet.Bsiresponse}
 * dipetakan di {@code WEB-INF/web.xml} pada URL {@code /BsiResponse}. Servlet
 * membaca badan permintaan, mengambil {@code client_id} dan blok {@code data},
 * lalu mendekripsinya dengan {@code com.bni.encrypt.BNIHash#parseData} memakai
 * kunci {@code bsi_password} dari tabel konfigurasi — pustaka enkripsi yang
 * sama dengan paket BNI, karena BSI e-Collection memakai produk gateway dari
 * keluarga teknologi yang sama. Kegagalan dekripsi berfungsi sebagai
 * autentikasi kriptografis callback. Alamat IP pemanggil juga dicocokkan ke
 * {@code BankHost} lewat
 * {@code PembayaranUtil#getBankHost(String, String)}, namun hasil pencocokan
 * itu dipakai untuk pencatatan log, bukan sebagai penolakan.
 * <p>
 * Jalur cadangan tersedia: {@code ais.action.master.bsi.BsiBackandProsess}
 * membaca {@link #getKeterangan()} sebagai JSON saat melakukan pemeriksaan
 * ulang status, bila konfigurasi
 * {@code aktifkan_check_ulang_otomatis_pembayaran_via_bsi} aktif.
 *
 * <h3>Catatan keamanan</h3>
 *
 * Kolom {@link #getCallback() callback} bertipe {@code text} dan menyimpan
 * payload notifikasi bank apa adanya (dapat memuat nomor Virtual Account,
 * {@code trx_id}, dan nominal) tanpa masking, sama seperti kolom
 * {@code request}/{@code response} pada {@link BsiRequest}. Kelas beranotasi
 * {@link Audited} sehingga setiap versi ikut digandakan ke tabel revisi
 * {@code bsi_response_AUD}; menghapus baris {@code bsi_response} tidak
 * menghapus jejak payload di sana. Entitas ini juga tidak memiliki kolom
 * kepemilikan/tenant.
 *
 * @see ais.database.model.bni.BniRequest
 * @see BsiRequest
 * @see BsiRequestDetail
 * @see BsiRequestDetailBiaya
 * @see ais.action.servlet.Bsiresponse
 * @see ais.action.master.bsi.BsiBackandProsess
 */
@Entity
@org.hibernate.annotations.Entity(
    dynamicInsert = true,
    dynamicUpdate = true
)
@Audited
@Table(schema = "public", name = "bsi_response")



public class BsiResponse extends GeneralValueObject {

	/** Status pembayaran: tagihan sudah terbit namun uang belum masuk. */
	public final static String PENDING = "pending";
	/** Status pembayaran: uang sudah diterima bank dan transaksi dianggap lunas. */
	public final static String BERHASIL = "berhasil";
	/** Status pembayaran: notifikasi diterima dan sedang direkonsiliasi AIS. */
	public final static String SEDANG_DIPROSES = "Sedang diproses";
	/** Status pembayaran: transaksi dibatalkan sebelum terbayar. */
	public final static String BATAL = "Batal";
	/** Status pembayaran: dana dikembalikan ke pembayar. */
	public final static String REFUND = "Refund";

	/**
	 *
	 * Nomor versi serialisasi entitas; JANGAN diubah agar data lama tetap terbaca.
	 */
	private static final long serialVersionUID = 2463821327548439808L;
	/** Kunci utama (identity, dibangkitkan basis data). */
	private Long id;
	/** Nama pengguna terakhir yang mengubah baris ini (field audit bayangan). */
	private String oleh;
	/** Identitas (id) pengguna terakhir yang mengubah baris ini (field audit bayangan). */
	private String olehId;

	/**
	 * Mengembalikan identitas pengguna terakhir yang menyentuh baris ini.
	 *
	 * @return id pengguna audit, atau {@code null} bila belum pernah diisi.
	 */
	public String getOlehId() {
		return olehId;
	}

	/**
	 * Menetapkan identitas pengguna audit.
	 * <p>
	 * <b>Setter satu arah:</b> nilai {@code null} atau string kosong DIABAIKAN
	 * secara diam-diam.
	 *
	 * @param olehId id pengguna; diabaikan bila kosong.
	 */
	public void setOlehId(String olehId) {if (olehId == null || olehId.trim().isEmpty()) {return;}
		this.olehId = olehId;
	}

	/**
	 * Menetapkan nama pengguna audit.
	 * <p>
	 * <b>Setter satu arah:</b> nilai {@code null} atau string kosong DIABAIKAN
	 * secara diam-diam.
	 *
	 * @param oleh nama pengguna; diabaikan bila kosong.
	 */
	public void setOleh(String oleh) {if (oleh == null || oleh.trim().isEmpty()) {return;}
		this.oleh = oleh;
	}

	/**
	 * Mengembalikan nama pengguna terakhir yang menyentuh baris ini.
	 *
	 * @return nama pengguna audit, atau {@code null} bila belum pernah diisi.
	 */
	public String getOleh() {
		return oleh;
	}

	/**
	 * Kait daur hidup JPA yang dipanggil tepat sebelum {@code UPDATE};
	 * mendelegasikan pengisian jejak audit ke
	 * {@code ais.database.hibernate.AuditTimestampInterceptor#ubah(Object)}.
	 * Keharusan teknis mekanisme audit AIS, bukan logika bisnis.
	 */
	@javax.persistence.PreUpdate protected void onUpdate() { ais.database.hibernate.AuditTimestampInterceptor.ubah(this);}     /** Stempel waktu perubahan terakhir; diinisialisasi ke waktu server saat objek dibuat. */
	private Date tanggal_dirubah = ais.ui.util.WaktuUtil.getDate();

	/**
	 * Menetapkan stempel waktu perubahan terakhir.
	 *
	 * @param tanggal_dirubah waktu perubahan.
	 */
	public void setTanggal_dirubah(Date tanggal_dirubah) {
		this.tanggal_dirubah = tanggal_dirubah;
	}

	/**
	 * Mengembalikan stempel waktu perubahan terakhir apa adanya.
	 *
	 * @return stempel waktu perubahan, atau {@code null}.
	 */
	@Temporal(TemporalType.TIMESTAMP)
	public Date getTanggal_dirubah() {
		return tanggal_dirubah;
	}

	/**
	 * Representasi teks ringkas untuk kombo/daftar ZK dan berkas log.
	 *
	 * @return gabungan {@code id} dan {@code nama} (session id BSI) dipisah tanda hubung.
	 */
	public String toString() {
		return id + "-" + nama;
	}

	/** Session id BSI; dipetakan ke kolom {@code sid} bertipe {@code text}. */
	private String nama;
	/** Status pembayaran versi AIS; lihat konstanta {@link #PENDING} dan seterusnya. */
	private String status;
	/** Kode status numerik dari bank; default {@code "0"}. */
	private String kodeStatus;
	/** Nomor transaksi bank; kunci pencocokan ke {@link BsiRequest#getTrxId()}. */
	private String trxId;
	/** Identitas merchant pada notifikasi; disalin balik ke {@link BsiRequest#getMerchant()}. */
	private String merchant;
	/** Keterangan notifikasi bank (kolom {@code text}); dibaca sebagai JSON oleh penjadwal. */
	private String keterangan;
	/** Payload notifikasi MENTAH dari bank (kolom {@code text}). */
	private String callback;

	/** Konstruktor tanpa argumen yang diwajibkan Hibernate/JPA. */
	public BsiResponse() {
	}

	/**
	 * Mengembalikan kunci utama baris ini.
	 *
	 * @return id baris, atau {@code null} bila belum di-persist.
	 */
	@Id
	@GeneratedValue(strategy = IDENTITY)
	@Column(name = "id", insertable = false, unique = true, nullable = false)
	public Long getId() {
		return this.id;
	}

	/**
	 * Menetapkan kunci utama baris ini.
	 *
	 * @param id kunci utama.
	 */
	public void setId(Long id) {
		this.id = id;
	}

	/**
	 * Mengembalikan session id BSI yang tersimpan pada kolom {@code sid}.
	 * <p>
	 * Perhatikan perbedaan nama kolom terhadap {@link BsiRequest#getNama()}
	 * yang memakai kolom {@code session_id} — pola penamaan antar-entitas di
	 * paket ini TIDAK seragam (sama seperti pada paket BNI dan BRI). Meski nama
	 * properti Java-nya {@code nama} (konvensi {@link GeneralValueObject}),
	 * isinya pengenal sesi, bukan nama orang. Nilai dipangkas spasi tepi
	 * sebelum dikembalikan.
	 *
	 * @return session id yang sudah di-{@code trim}, atau {@code null}.
	 */
	@Column(name = "sid", columnDefinition = "text")
	public String getNama() {
		return this.nama == null ? null : this.nama.trim();
	}

	/**
	 * Menetapkan session id BSI.
	 *
	 * @param nama session id dari notifikasi bank.
	 */
	public void setNama(String nama) {
		this.nama = nama;
	}

	/**
	 * Mengembalikan nomor transaksi bank pada notifikasi ini.
	 * <p>
	 * Kunci pencocokan ke {@link BsiRequest#getTrxId()} saat servlet callback
	 * mencari transaksi yang dimaksud. Berbeda dari
	 * {@link BsiRequest#getTrxId()} yang mengembalikan string kosong bila
	 * kosong, getter ini mengembalikan nilai apa adanya termasuk {@code null}.
	 *
	 * @return nomor transaksi bank, atau {@code null}.
	 */
	public String getTrxId() {
		return trxId;
	}

	/**
	 * Menetapkan nomor transaksi bank pada notifikasi ini.
	 *
	 * @param trxId nomor transaksi bank.
	 */
	public void setTrxId(String trxId) {
		this.trxId = trxId;
	}

	/**
	 * Mengembalikan identitas merchant pada notifikasi ini.
	 * <p>
	 * Nilai ini dianggap sumber kebenaran: {@link BsiRequest#getMerchant()}
	 * MENIMPA nilainya sendiri dengan nilai dari sini setiap kali dipanggil
	 * selagi tautan {@link BsiRequest#getBsiResponse()} terisi.
	 *
	 * @return identitas merchant, atau {@code null}.
	 */
	public String getMerchant() {
		return merchant;
	}

	/**
	 * Menetapkan identitas merchant pada notifikasi ini.
	 *
	 * @param merchant identitas merchant.
	 */
	public void setMerchant(String merchant) {
		this.merchant = merchant;
	}

	/**
	 * Mengembalikan status pembayaran versi AIS.
	 * <p>
	 * <b>Getter destruktif:</b> {@code null} dinormalkan menjadi string kosong
	 * dan ditulis balik ke field. Nilai yang diharapkan adalah salah satu
	 * konstanta {@link #PENDING}, {@link #BERHASIL},
	 * {@link #SEDANG_DIPROSES}, {@link #BATAL}, atau {@link #REFUND} — namun
	 * kolom ini bertipe teks bebas dan tidak ada penjagaan yang memaksa nilai
	 * berasal dari daftar tersebut.
	 *
	 * @return status pembayaran; tidak pernah {@code null}.
	 */
	public String getStatus() {
		if (status == null) {
			status = "";
		}
		return status;
	}

	/**
	 * Menetapkan status pembayaran versi AIS.
	 *
	 * @param status status pembayaran; sebaiknya salah satu konstanta kelas ini.
	 */
	public void setStatus(String status) {
		this.status = status;
	}

	/**
	 * Mengembalikan keterangan notifikasi bank (kolom {@code text}).
	 * <p>
	 * <b>Getter destruktif:</b> {@code null} dinormalkan menjadi string kosong
	 * dan ditulis balik ke field agar aman digabung ke string tampilan.
	 * <p>
	 * <b>Perhatian:</b> kolom ini tidak sekadar teks bebas —
	 * {@code ais.action.master.bsi.BsiBackandProsess} MENGURAINYA SEBAGAI JSON
	 * ({@code new JSONObject(bsiResponse.getKeterangan())}) saat melakukan
	 * pemeriksaan ulang status, dan {@code ais.action.servlet.Bsiresponse}
	 * melakukan hal serupa. Mengisi kolom ini dengan teks bebas non-JSON dapat
	 * membuat pemeriksaan ulang gagal.
	 *
	 * @return keterangan notifikasi; tidak pernah {@code null}.
	 */
	@Column(columnDefinition = "text")
	public String getKeterangan() {
		if (keterangan == null) {
			keterangan = "";
		}
		return keterangan;
	}

	/**
	 * Menetapkan keterangan notifikasi bank.
	 * <p>
	 * Isi nilai berupa JSON yang valid; lihat peringatan pada
	 * {@link #getKeterangan()}.
	 *
	 * @param keterangan keterangan notifikasi.
	 */
	public void setKeterangan(String keterangan) {
		this.keterangan = keterangan;
	}

	/**
	 * Mengembalikan payload notifikasi MENTAH dari bank (kolom {@code text}).
	 * <p>
	 * <b>Catatan keamanan:</b> kolom ini menyimpan isi callback apa adanya —
	 * dapat memuat nomor Virtual Account, {@code trx_id}, dan nominal — tanpa
	 * masking, dan ikut digandakan ke tabel revisi Envers
	 * {@code bsi_response_AUD}. Perlakukan seperti
	 * {@link BsiRequest#getRequest()} dan {@link BsiRequest#getResponse()}:
	 * jangan ditampilkan pada antarmuka berhak-akses-rendah dan pertimbangkan
	 * masking sebelum diekspor.
	 *
	 * @return payload notifikasi mentah, atau {@code null}.
	 */
	@Column(columnDefinition = "text")
	public String getCallback() {
		return callback;
	}

	/**
	 * Menetapkan payload notifikasi mentah dari bank.
	 *
	 * @param callback payload notifikasi.
	 */
	public void setCallback(String callback) {
		this.callback = callback;
	}

	/**
	 * Mengembalikan kode status numerik dari bank.
	 * <p>
	 * <b>Getter destruktif:</b> bila belum pernah diisi, nilai {@code "0"}
	 * ditulis balik ke field. Perhatikan bahwa {@code "0"} di sini adalah
	 * penanda "belum ada kode", BUKAN kode sukses — pada skema BSI e-Collection
	 * kode sukses justru {@code "000"} (lihat peta
	 * {@code ais.action.master.bsi.BsiRequestAction#statses}). Jangan
	 * menyimpulkan keberhasilan pembayaran dari nilai ini tanpa memeriksa
	 * {@link #getStatus()}.
	 *
	 * @return kode status bank; tidak pernah {@code null}.
	 */
	public String getKodeStatus() {
		if (kodeStatus == null) {
			kodeStatus = "0";
		}
		return kodeStatus;
	}

	/**
	 * Menetapkan kode status numerik dari bank.
	 *
	 * @param kodeStatus kode status bank.
	 */
	public void setKodeStatus(String kodeStatus) {
		this.kodeStatus = kodeStatus;
	}

}
